CREATE TYPE "UserRole" AS ENUM ('SOLICITANTE', 'ATENDENTE');
CREATE TYPE "RequestStatus" AS ENUM ('ABERTO', 'EM_ATENDIMENTO', 'CONCLUIDO');
CREATE TABLE "users" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"password_hash" TEXT NOT NULL,"role" "UserRole" NOT NULL DEFAULT 'SOLICITANTE',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "users_pkey" PRIMARY KEY ("id"));
CREATE TABLE "categories" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "categories_pkey" PRIMARY KEY ("id"));
CREATE TABLE "requests" ("id" TEXT NOT NULL,"code" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"status" "RequestStatus" NOT NULL DEFAULT 'ABERTO',"requester_id" TEXT NOT NULL,"category_id" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "requests_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "users_email_key" ON "users"("email"); CREATE UNIQUE INDEX "categories_name_key" ON "categories"("name"); CREATE UNIQUE INDEX "requests_code_key" ON "requests"("code"); CREATE INDEX "requests_requester_id_idx" ON "requests"("requester_id"); CREATE INDEX "requests_status_idx" ON "requests"("status"); CREATE INDEX "requests_category_id_idx" ON "requests"("category_id"); CREATE INDEX "requests_created_at_idx" ON "requests"("created_at");
ALTER TABLE "requests" ADD CONSTRAINT "requests_requester_id_fkey" FOREIGN KEY ("requester_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "requests" ADD CONSTRAINT "requests_category_id_fkey" FOREIGN KEY ("category_id") REFERENCES "categories"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
